class CustomHPOStrategy:
    """Default-anchored, fidelity-calibrated contrastive trust-region search."""

    def __init__(self, seed: int = 42):
        self.seed = seed
        self.rng = np.random.RandomState(seed)
        self.startup = 6
        self.n_candidates = 56

    def _encode(self, config: Dict[str, Any], space: SearchSpace) -> np.ndarray:
        x = []
        for p in space.params:
            v = config[p.name]
            if p.type == "categorical":
                x.append(p.choices.index(v) / max(len(p.choices) - 1, 1))
            else:
                lo, hi = (np.log(p.low), np.log(p.high)) if p.log_scale else (p.low, p.high)
                z = np.log(max(float(v), p.low)) if p.log_scale else float(v)
                x.append((z - lo) / (hi - lo + 1e-12))
        return np.array(x, dtype=float)

    def _decode(self, x: np.ndarray, space: SearchSpace) -> Dict[str, Any]:
        cfg = {}
        for i, p in enumerate(space.params):
            v = float(np.clip(x[i], 0.0, 1.0))
            if p.type == "categorical":
                j = min(int(round(v * max(len(p.choices) - 1, 1))), len(p.choices) - 1)
                cfg[p.name] = p.choices[j]
            elif p.type == "float":
                cfg[p.name] = float(np.exp(np.log(p.low) + v * (np.log(p.high) - np.log(p.low)))) if p.log_scale else float(p.low + v * (p.high - p.low))
            else:
                z = np.exp(np.log(p.low) + v * (np.log(p.high) - np.log(p.low))) if p.log_scale else p.low + v * (p.high - p.low)
                cfg[p.name] = int(round(z))
        return cfg

    def _prior(self, space: SearchSpace) -> Dict[str, Any]:
        pri = {"n_estimators": 100, "max_depth": 3, "learning_rate": 0.1, "subsample": 1.0,
               "min_samples_split": 2, "min_samples_leaf": 1, "C": 1.0, "gamma": 0.01,
               "hidden_layer_1": 64, "hidden_layer_2": 32, "learning_rate_init": 1e-3,
               "alpha": 1e-4, "batch_size": 64}
        cfg = {}
        for p in space.params:
            if p.type == "categorical":
                cfg[p.name] = p.choices[0]
            else:
                v = pri.get(p.name, np.sqrt(p.low * p.high) if p.log_scale else 0.5 * (p.low + p.high))
                cfg[p.name] = int(round(v)) if p.type == "int" else float(v)
        return space.clip(cfg)

    def suggest(
        self,
        space: SearchSpace,
        history: List[Trial],
        budget_left: int,
    ) -> Tuple[Dict[str, Any], float]:
        d, base = space.dim, self._encode(self._prior(space), space)
        if not history:
            return self._prior(space), 1.0
        if len(history) < self.startup:
            z = ((len(history) + 1) * np.sqrt(np.arange(1, d + 1) + self.seed)) % 1.0 - 0.5
            x = np.clip(base + (0.55 if len(history) == 1 else 0.35) * z, 0.0, 1.0)
            fid = 1.0 if d <= 3 or len(history) < 3 or budget_left <= 2 else 0.5
            return self._decode(x, space), fid

        X = np.array([self._encode(t.config, space) for t in history])
        b = np.array([t.budget for t in history], dtype=float)
        s = np.array([t.score for t in history], dtype=float)
        fb = np.round(b, 2)
        meds = {f: np.median(s[fb == f]) for f in np.unique(fb)}
        ref = max(meds.values())
        y = np.array([s[i] + 0.5 * (ref - meds[fb[i]]) for i in range(len(s))], dtype=float)
        y = (y - y.mean()) / (y.std() + 1e-9)
        order = np.argsort(y)
        m = max(3, int(np.sqrt(len(history))))
        elite = X[order[-m:]]
        bad = X[order[:max(2, len(history) // 3)]]
        w = np.exp(y[order[-m:]] - y[order[-m:]].max())
        mean = (elite * w[:, None]).sum(0) / (w.sum() + 1e-12)
        scale = np.clip(np.sqrt(((elite - mean) ** 2 * w[:, None]).sum(0) / (w.sum() + 1e-12)) + 0.08, 0.08, 0.35)
        spent = float(np.sum(b))
        prog = spent / max(spent + max(budget_left, 1), 1.0)
        n_full = int(np.sum(b >= 0.99))

        best_prom, prom_val = None, -1e9
        if d > 4 and prog < 0.4:
            seen = {}
            for i, t in enumerate(history):
                key = tuple(t.config[p.name] for p in space.params)
                seen.setdefault(key, []).append(i)
            for idxs in seen.values():
                if np.max(b[idxs]) < 0.99:
                    j = idxs[int(np.argmax(y[idxs]))]
                    if y[j] > prom_val:
                        best_prom, prom_val = history[j].config, y[j]
            if best_prom is not None and (n_full < 4 or prom_val > np.quantile(y, 0.7)):
                return best_prom, 1.0 if budget_left > 0 else 0.5

        bestx, bestv, bestnov = X[np.argmax(y)], -1e18, 0.0
        for k in range(self.n_candidates + 3):
            if k == 0:
                x = base
            elif k == 1:
                x = mean
            elif k == 2:
                x = bestx
            else:
                r = self.rng.rand()
                if r < 0.18:
                    x = self.rng.rand(d)
                elif r < 0.62:
                    e = elite[self.rng.randint(len(elite))]
                    x = 0.7 * mean + 0.3 * e + self.rng.randn(d) * scale * (0.55 - 0.25 * prog)
                elif r < 0.86:
                    a, c, e = X[self.rng.choice(len(X), 3, replace=False)]
                    x = bestx + 0.7 * (a - c) + 0.2 * (mean - e) + self.rng.randn(d) * scale * 0.08
                else:
                    x = 2.0 * mean - X[self.rng.randint(len(X))] + self.rng.randn(d) * 0.12
            x = np.clip(x, 0.0, 1.0)
            ker = np.exp(-0.5 * np.sum(((X - x) / scale) ** 2, axis=1)) * (0.35 + 0.65 * b)
            sw = ker.sum() + 1e-12
            mu = float((ker * y).sum() / sw)
            sd = float(np.sqrt((ker * (y - mu) ** 2).sum() / sw + 0.15 / sw))
            z = (mu - np.max(y)) / (sd + 1e-12)
            ei = (mu - np.max(y)) * scipy_norm.cdf(z) + sd * scipy_norm.pdf(z)
            cg = np.exp(-0.5 * np.sum(((elite - x) / scale) ** 2, axis=1)).mean()
            cb = np.exp(-0.5 * np.sum(((bad - x) / (scale + 0.05)) ** 2, axis=1)).mean()
            nov = float(np.sqrt(np.sum((X - x) ** 2, axis=1)).min())
            val = ei + 0.25 * (cg - cb) + 0.05 * nov - 0.2 * (nov < 0.03)
            if val > bestv:
                bestx, bestv, bestnov = x, val, nov

        fid = 0.5 if (d > 4 and prog < 0.15 and n_full < 4 and bestnov > 0.12 and budget_left > 2) else 1.0
        cfg = self._decode(bestx, space)
        seen = {tuple(t.config[p.name] for p in space.params) for t in history}
        if tuple(cfg[p.name] for p in space.params) in seen and fid >= 0.99:
            for _ in range(8):
                cfg = self._decode(np.clip(bestx + self.rng.randn(d) * 0.12, 0.0, 1.0), space)
                if tuple(cfg[p.name] for p in space.params) not in seen:
                    break
        return cfg, (0.5 if d > 4 else 1.0) if budget_left <= 0 else fid


