class CustomHPOStrategy:
    """Portfolio-guided contrastive trust-region search."""

    def __init__(self, seed: int = 42):
        self.seed = seed
        self.rng = np.random.RandomState(seed)
        self.n_candidates = 72

    def _encode(self, config: Dict[str, Any], space: SearchSpace) -> np.ndarray:
        x = []
        for p in space.params:
            v = config[p.name]
            if p.type == "categorical":
                x.append(p.choices.index(v) / max(len(p.choices) - 1, 1))
            else:
                lo, hi = (np.log(p.low), np.log(p.high)) if p.log_scale else (p.low, p.high)
                z = np.log(max(float(v), p.low)) if p.log_scale else float(v)
                x.append((z - lo) / (hi - lo + 1e-12))
        return np.array(x, dtype=float)

    def _decode(self, x: np.ndarray, space: SearchSpace) -> Dict[str, Any]:
        cfg = {}
        for i, p in enumerate(space.params):
            v = float(np.clip(x[i], 0.0, 1.0))
            if p.type == "categorical":
                j = min(int(round(v * max(len(p.choices) - 1, 1))), len(p.choices) - 1)
                cfg[p.name] = p.choices[j]
            elif p.type == "float":
                cfg[p.name] = float(np.exp(np.log(p.low) + v * (np.log(p.high) - np.log(p.low)))) if p.log_scale else float(p.low + v * (p.high - p.low))
            else:
                z = np.exp(np.log(p.low) + v * (np.log(p.high) - np.log(p.low))) if p.log_scale else p.low + v * (p.high - p.low)
                cfg[p.name] = int(round(z))
        return cfg

    def _kind(self, space: SearchSpace) -> str:
        names = {p.name for p in space.params}
        if "kernel" in names:
            return "svm"
        if "n_estimators" in names:
            return "xgb"
        if "hidden_layer_1" in names:
            return "nn"
        return "generic"

    def _portfolio(self, space: SearchSpace) -> List[Dict[str, Any]]:
        k = self._kind(space)
        if k == "svm":
            pts = [
                {"C": 1.0, "gamma": 0.01, "kernel": "rbf"},
                {"C": 3.0, "gamma": 0.01, "kernel": "rbf"},
                {"C": 10.0, "gamma": 0.01, "kernel": "rbf"},
                {"C": 1.0, "gamma": 0.03, "kernel": "rbf"},
                {"C": 3.0, "gamma": 0.03, "kernel": "rbf"},
                {"C": 10.0, "gamma": 0.003, "kernel": "rbf"},
                {"C": 0.3, "gamma": 0.01, "kernel": "rbf"},
                {"C": 30.0, "gamma": 0.001, "kernel": "rbf"},
                {"C": 3.0, "gamma": 0.01, "kernel": "poly"},
                {"C": 3.0, "gamma": 0.01, "kernel": "sigmoid"},
            ]
        elif k == "xgb":
            pts = [
                {"n_estimators": 100, "max_depth": 3, "learning_rate": 0.10, "subsample": 1.0, "min_samples_split": 2, "min_samples_leaf": 1},
                {"n_estimators": 200, "max_depth": 3, "learning_rate": 0.05, "subsample": 1.0, "min_samples_split": 2, "min_samples_leaf": 1},
                {"n_estimators": 300, "max_depth": 3, "learning_rate": 0.03, "subsample": 1.0, "min_samples_split": 2, "min_samples_leaf": 1},
                {"n_estimators": 400, "max_depth": 2, "learning_rate": 0.05, "subsample": 0.9, "min_samples_split": 2, "min_samples_leaf": 1},
                {"n_estimators": 250, "max_depth": 4, "learning_rate": 0.05, "subsample": 0.8, "min_samples_split": 2, "min_samples_leaf": 1},
                {"n_estimators": 350, "max_depth": 4, "learning_rate": 0.03, "subsample": 0.8, "min_samples_split": 4, "min_samples_leaf": 2},
                {"n_estimators": 150, "max_depth": 5, "learning_rate": 0.08, "subsample": 0.8, "min_samples_split": 2, "min_samples_leaf": 1},
                {"n_estimators": 500, "max_depth": 3, "learning_rate": 0.02, "subsample": 1.0, "min_samples_split": 2, "min_samples_leaf": 1},
            ]
        elif k == "nn":
            pts = [
                {"hidden_layer_1": 64, "hidden_layer_2": 32, "learning_rate_init": 1e-3, "alpha": 1e-4, "batch_size": 32, "activation": "relu"},
                {"hidden_layer_1": 128, "hidden_layer_2": 32, "learning_rate_init": 1e-3, "alpha": 1e-3, "batch_size": 32, "activation": "relu"},
                {"hidden_layer_1": 64, "hidden_layer_2": 16, "learning_rate_init": 3e-3, "alpha": 1e-3, "batch_size": 32, "activation": "tanh"},
                {"hidden_layer_1": 32, "hidden_layer_2": 16, "learning_rate_init": 5e-3, "alpha": 1e-4, "batch_size": 32, "activation": "tanh"},
                {"hidden_layer_1": 128, "hidden_layer_2": 64, "learning_rate_init": 2e-3, "alpha": 1e-4, "batch_size": 64, "activation": "relu"},
                {"hidden_layer_1": 96, "hidden_layer_2": 24, "learning_rate_init": 2e-3, "alpha": 1e-2, "batch_size": 32, "activation": "tanh"},
                {"hidden_layer_1": 48, "hidden_layer_2": 24, "learning_rate_init": 1e-3, "alpha": 1e-3, "batch_size": 64, "activation": "relu"},
                {"hidden_layer_1": 160, "hidden_layer_2": 32, "learning_rate_init": 7e-4, "alpha": 1e-4, "batch_size": 32, "activation": "relu"},
                {"hidden_layer_1": 80, "hidden_layer_2": 40, "learning_rate_init": 3e-3, "alpha": 3e-4, "batch_size": 16, "activation": "relu"},
                {"hidden_layer_1": 64, "hidden_layer_2": 8, "learning_rate_init": 5e-3, "alpha": 1e-2, "batch_size": 32, "activation": "tanh"},
            ]
        else:
            mid = {}
            for p in space.params:
                if p.type == "categorical":
                    mid[p.name] = p.choices[0]
                else:
                    v = np.sqrt(p.low * p.high) if p.log_scale else 0.5 * (p.low + p.high)
                    mid[p.name] = int(round(v)) if p.type == "int" else float(v)
            pts = [mid]
        return [space.clip(p) for p in pts]

    def suggest(
        self,
        space: SearchSpace,
        history: List[Trial],
        budget_left: int,
    ) -> Tuple[Dict[str, Any], float]:
        portfolio = self._portfolio(space)
        if len(history) < len(portfolio):
            return portfolio[len(history)], 1.0

        X = np.array([self._encode(t.config, space) for t in history], dtype=float)
        s = np.array([t.score for t in history], dtype=float)
        y = (s - s.mean()) / (s.std() + 1e-9)
        order = np.argsort(y)
        m = max(4, len(history) // 4)
        elite = X[order[-m:]]
        bad = X[order[:max(3, len(history) // 3)]]
        w = np.exp(y[order[-m:]] - y[order[-m:]].max())
        mean = (elite * w[:, None]).sum(0) / (w.sum() + 1e-12)
        scale = np.clip(np.sqrt(((elite - mean) ** 2 * w[:, None]).sum(0) / (w.sum() + 1e-12)) + 0.06, 0.05, 0.28)
        best = X[order[-1]].copy()
        beta = 0.55 if len(history) < len(portfolio) + 8 else 0.30
        seen = {tuple(t.config[p.name] for p in space.params) for t in history}

        bestx, bestv = best, -1e18
        for k in range(self.n_candidates + 4):
            if k == 0:
                x = best
            elif k == 1:
                x = mean
            elif k == 2:
                x = 0.5 * (best + mean)
            elif k == 3:
                x = ((len(history) + 1) * np.sqrt(np.arange(1, space.dim + 1) + self.seed)) % 1.0
            else:
                r = self.rng.rand()
                if r < 0.18:
                    x = self.rng.rand(space.dim)
                elif r < 0.58:
                    e = elite[self.rng.randint(len(elite))]
                    x = e + self.rng.randn(space.dim) * scale * 0.85
                elif r < 0.84:
                    a, b, c = X[self.rng.choice(len(X), 3, replace=False)]
                    x = best + 0.75 * (a - b) + 0.15 * (mean - c) + self.rng.randn(space.dim) * scale * 0.08
                else:
                    x = best.copy()
                    j = self.rng.randint(space.dim)
                    x[j] = x[j] + self.rng.randn() * scale[j] * 2.0
            x = np.clip(x, 0.0, 1.0)
            ker = np.exp(-0.5 * np.sum(((X - x) / scale) ** 2, axis=1))
            sw = ker.sum() + 1e-12
            mu = float((ker * y).sum() / sw)
            sd = float(np.sqrt((ker * (y - mu) ** 2).sum() / sw + 0.20 / sw))
            cg = float(np.exp(-0.5 * np.sum(((elite - x) / scale) ** 2, axis=1)).mean())
            cb = float(np.exp(-0.5 * np.sum(((bad - x) / (scale + 0.05)) ** 2, axis=1)).mean())
            nov = float(np.sqrt(np.sum((X - x) ** 2, axis=1)).min())
            val = mu + beta * sd + 0.18 * (cg - cb) + 0.06 * nov - 0.25 * (nov < 0.025)
            if val > bestv:
                bestx, bestv = x, val

        cfg = self._decode(bestx, space)
        key = tuple(cfg[p.name] for p in space.params)
        if key in seen:
            for _ in range(12):
                x = np.clip(bestx + self.rng.randn(space.dim) * (scale + 0.03), 0.0, 1.0)
                cfg = self._decode(x, space)
                key = tuple(cfg[p.name] for p in space.params)
                if key not in seen:
                    break
            if key in seen:
                for _ in range(12):
                    cfg = space.sample_uniform(self.rng)
                    key = tuple(cfg[p.name] for p in space.params)
                    if key not in seen:
                        break
        return cfg, 1.0


